const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/1234/projects/5678/schedules/1234/activity_links',
  qs: {
    'filters[id]': 'SOME_STRING_VALUE',
    'filters[from_activity]': 'SOME_STRING_VALUE',
    'filters[to_activity]': 'SOME_STRING_VALUE',
    'filters[updated_at][gt]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/1234/projects/5678/schedules/1234/activity_links?filters%5Bid%5D=SOME_STRING_VALUE&filters%5Bfrom_activity%5D=SOME_STRING_VALUE&filters%5Bto_activity%5D=SOME_STRING_VALUE&filters%5Bupdated_at%5D%5Bgt%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

